def is_perrin(n):
    if n == 0:
        return 3
    elif n == 1 or n == 2:
        return 2

def perrin_sequence(n):
    if n < 0:
        raise ValueError("Input must be a non-negative integer")

    sequence = [is_perrin(i) for i in range(n+1)]
    for i in range(3, n+1):
        sequence[i] = (sequence[i-2] + sequence[i-3]) % 1000000007

    return sum(sequence)

def calculate_sum_of_perrin_numbers(n):
    if n < 0:
        raise ValueError("Input must be a non-negative integer")

    return perrin_sequence(n)
```

