def strange_sort_list(lst):
    if not lst:
        return []

    sorted_lst = []
    seen = set()

    while lst:
        min_val = float('inf')
        max_val = -float('inf')

        for num in lst:
            if num not in seen:
                if num < min_val:
                    min_val = num
                if num > max_val:
                    max_val = num

        sorted_lst.append(min_val)
        seen.add(min_val)

        if max_val != min_val:  # Avoid adding the same number twice
            sorted_lst.append(max_val)
            seen.add(max_val)

        lst.remove(min_val)
        if max_val in lst:
            lst.remove(max_val)

    return sorted_lst

