def are_divisor_sums_equal(a: int, b: int) -> bool:
    def sum_of_divisors(n):
        divisors_sum = 1  # Start with 1 because it's always a divisor for any n > 0
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                divisors_sum += i
                if i != n // i:  # Add the quotient only if it's different from i (to avoid adding square root twice)
                    divisors_sum += n // i
        return divisors_sum

    return sum_of_divisors(a) == sum_of_divisors(b)
