def split_words(txt):
    if ',' in txt:
        return txt.split(',')
    elif all(c.isspace() for c in txt):
        return [txt]
    else:
        count = sum(1 for c in txt if 'a' <= c.lower() <= 'z' and (ord(c) - ord('a')) % 2 == 0)
        return count
```

